response:
**Gates before launch**

I assumed the r03 runner command (`node triage/run.js --config <id>`) and the ticket file (`spe/evals/tasks/tickets.jsonl`) carry over from `spe/evals/harness/r03-workflow.js`. Both are arguments, so you can change them. Before I launch, I run these gates in order:

1. I confirm that `git log` shows the `SPE r04 predict` commit, and that `spe/predictions/r04.yaml` and `spe/plans/r04.md` have no changes since it.
2. I check that the tickets file and `spe/evals/tasks/answers.json` both have 50 matching ticket IDs. The approved plan says 50 tickets, but the eval set has 40 historical tickets. If only 40 exist, I halt and ask you. The predictions were made for 50 tickets, so this is your decision. I do not edit the prediction.
3. I run `python3 spe/evals/graders/grade.py --selftest`. The oracle answer must pass, and the empty and wrong answers must fail.
4. I regrade the round 3 outputs with today's `grade.py` as a control. If any number differs from the logged r03 numbers, that is a grader change. I log it in `spe/failures.md` and stop.
5. I do a dry run with `{round: 4, limitTickets: 1, trials: 2, capUsd: 2, outDir: "runs/r04-dryrun"}`. That is 2 cells. It must return valid trial records, a clean scan, grader rows, and judge scores.
6. I commit the script as `SPE r04 evaluate (harness)`. Then I launch with `{round: 4, configs: ["B", "C2"], trials: 5, expectedTasks: 50, capUsd: 40, maxAgents: 300, topUpPerCell: 3, topUpMax: 60}`.

The Opus judge comes from the same model family as the Sonnet agent under test. No judge from another family is available, so the script logs that limit.

The spend estimate is unmeasured. It is about $15 for 500 triage runs, about $13 for 50 judge batches, and about $3 for top-ups. That is under the $40 cap.

**spe/evals/harness/r04-workflow.js**

```js
export const meta = {
  name: 'spe-triage-eval',
  description: 'SPE eval of the triage support agent. Runs each config on every ticket, grades category and priority with grade.py, judges reply tone with an Opus judge, tops up split cells, and ends with failure analysis and a completeness critic.',
  phases: [
    { title: 'Gate' },
    { title: 'Trials' },
    { title: 'Scan' },
    { title: 'Grade' },
    { title: 'Judge' },
    { title: 'Top-up' },
    { title: 'Synthesis' },
  ],
};

// ---------- Round and arguments ----------
const ROUND = args.round;
if (!Number.isInteger(ROUND)) throw new Error('args.round is required, for example 4');
const RR = 'r' + String(ROUND).padStart(2, '0');

const CONFIGS = args.configs ?? ['B', 'C2'];
const TRIALS = args.trials ?? 5;
const EXPECTED_TASKS = args.expectedTasks ?? 50;
const LIMIT_TICKETS = args.limitTickets ?? null;   // dry run: first N tickets per config
const CAP_USD = args.capUsd ?? 40;
const EST_TRIAL_USD = args.estTrialUsd ?? 0.03;    // unmeasured estimate per triage run
const EST_JUDGE_USD = args.estJudgeUsd ?? 0.25;    // unmeasured estimate per Opus judge batch
const MAX_AGENTS = args.maxAgents ?? 300;
const WAVE = args.wave ?? 10;                      // cells per wave, so real spend updates between waves
const TOPUP_PER_CELL = args.topUpPerCell ?? 3;
const TOPUP_MAX = args.topUpMax ?? 60;
const RUNNER = args.runner ?? 'node triage/run.js';
const TICKETS_FILE = args.ticketsFile ?? 'spe/evals/tasks/tickets.jsonl';
const OUT = args.outDir ?? `runs/${RR}`;
const ANSWERS = 'spe/evals/tasks/answers.json';
const GRADER = 'spe/evals/graders/grade.py';
const RUBRIC = 'spe/evals/graders/judge.md';
const FORBIDDEN = ['spe/evals/', 'spe/predictions/', 'spe/plans/', 'spe/spec/', 'spe/prediction-log.md', 'spe/failures.md'];
const MODEL = 'opus';

log(`${RR}: configs ${CONFIGS.join(', ')}, ${TRIALS} trials per cell, spend cap $${CAP_USD}, agent cap ${MAX_AGENTS}`);
log('Judge note: the tone judge is Opus, the same family as the Sonnet agent under test. No other-family judge is available.');

// ---------- Budget ----------
let spentUsd = 0;
let reservedUsd = 0;
let agentsUsed = 0;
const skipped = [];

function reserve(usd, what) {
  if (agentsUsed + 1 > MAX_AGENTS) {
    skipped.push({ what, reason: 'agent cap', usd });
    log(`SKIP ${what}: agent cap ${MAX_AGENTS} reached`);
    return false;
  }
  if (spentUsd + reservedUsd + usd > CAP_USD) {
    skipped.push({ what, reason: 'spend cap', usd });
    log(`SKIP ${what}: would cross $${CAP_USD} (spent ${spentUsd.toFixed(2)}, reserved ${reservedUsd.toFixed(2)})`);
    return false;
  }
  reservedUsd += usd;
  agentsUsed += 1;
  return true;
}

function settle(heldUsd, actualUsd) {
  reservedUsd -= heldUsd;
  spentUsd += actualUsd ?? heldUsd;
}

function reserveTrials(want, what) {
  let n = want;
  while (n > 0 && spentUsd + reservedUsd + n * EST_TRIAL_USD > CAP_USD) n--;
  if (n < want) {
    skipped.push({ what, reason: 'spend cap', trialsSkipped: want - n });
    log(`SKIP ${want - n} trial(s) of ${what}: spend cap`);
  }
  if (n === 0) return 0;
  return reserve(n * EST_TRIAL_USD, what) ? n : 0;
}

// ---------- Helpers ----------
const key = (cfg, ticket, trial) => `${cfg}|${ticket}|${trial}`;
const range = (start, n) => Array.from({ length: n }, (_, i) => start + i);

async function inWaves(items, size, fn) {
  const out = [];
  for (let i = 0; i < items.length; i += size) {
    const part = await parallel(items.slice(i, i + size).map((x) => () => fn(x)));
    out.push(...part.flat());
  }
  return out;
}

function seededShuffle(arr, seed) {
  let h = 2166136261;
  for (const c of seed) h = Math.imul(h ^ c.charCodeAt(0), 16777619);
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    h = Math.imul(h ^ (h >>> 13), 1597334677);
    const j = Math.abs(h) % (i + 1);
    [a[i], a[j]] = [a[j], a[i]];
  }
  return a;
}

// ---------- Schemas ----------
const GATE_SCHEMA = {
  type: 'object',
  required: ['tickets', 'answerIds', 'selftest'],
  properties: {
    tickets: {
      type: 'array',
      items: {
        type: 'object',
        required: ['id', 'subject', 'body'],
        properties: { id: { type: 'string' }, subject: { type: 'string' }, body: { type: 'string' } },
      },
    },
    answerIds: { type: 'array', items: { type: 'string' } },
    selftest: {
      type: 'object',
      required: ['oraclePass', 'emptyFail', 'wrongFail', 'output'],
      properties: {
        oraclePass: { type: 'boolean' },
        emptyFail: { type: 'boolean' },
        wrongFail: { type: 'boolean' },
        output: { type: 'string' },
      },
    },
  },
};

const TRIAL_SCHEMA = {
  type: 'object',
  required: ['trials'],
  properties: {
    trials: {
      type: 'array',
      items: {
        type: 'object',
        required: ['trial', 'status', 'outFile', 'transcriptFile'],
        properties: {
          trial: { type: 'integer' },
          status: { enum: ['completed', 'harness_error', 'rate_limited'] },
          error: { type: 'string' },
          outFile: { type: 'string' },
          transcriptFile: { type: 'string' },
          category: { enum: ['billing', 'bug', 'how-to', 'account', 'outage', 'invalid'] },
          priority: { enum: ['P1', 'P2', 'P3', 'P4', 'invalid'] },
          reply: { type: 'string' },
          runtimeS: { type: 'number' },
          toolCalls: { type: 'integer' },
          tokensIn: { type: 'integer' },
          tokensOut: { type: 'integer' },
          toolErrors: { type: 'integer' },
          costUsd: { type: 'number' },
        },
      },
    },
  },
};

const SCAN_SCHEMA = {
  type: 'object',
  required: ['hits', 'missing'],
  properties: {
    hits: {
      type: 'array',
      items: {
        type: 'object',
        required: ['ticket', 'trial', 'file', 'match'],
        properties: { ticket: { type: 'string' }, trial: { type: 'integer' }, file: { type: 'string' }, match: { type: 'string' } },
      },
    },
    missing: {
      type: 'array',
      items: { type: 'object', required: ['ticket', 'trial'], properties: { ticket: { type: 'string' }, trial: { type: 'integer' } } },
    },
  },
};

const GRADE_SCHEMA = {
  type: 'object',
  required: ['ok', 'results'],
  properties: {
    ok: { type: 'boolean' },
    error: { type: 'string' },
    results: {
      type: 'array',
      items: {
        type: 'object',
        required: ['ticket', 'trial', 'categoryOk', 'priorityOk'],
        properties: {
          ticket: { type: 'string' },
          trial: { type: 'integer' },
          categoryOk: { type: 'boolean' },
          priorityOk: { type: 'boolean' },
        },
      },
    },
  },
};

const JUDGE_SCHEMA = {
  type: 'object',
  required: ['scores'],
  properties: {
    scores: {
      type: 'array',
      items: {
        type: 'object',
        required: ['rid', 'tonePass', 'score', 'reason'],
        properties: {
          rid: { type: 'string' },
          tonePass: { type: 'boolean' },
          score: { type: 'integer', minimum: 1, maximum: 5 },
          reason: { type: 'string' },
        },
      },
    },
  },
};

const FAILURE_SCHEMA = {
  type: 'object',
  required: ['failureTypes'],
  properties: {
    failureTypes: {
      type: 'array',
      items: {
        type: 'object',
        required: ['name', 'kind', 'what', 'howToSpot', 'seenIn', 'proposedFix', 'existingId'],
        properties: {
          name: { type: 'string' },
          kind: { enum: ['agent', 'grader', 'judge', 'harness', 'task'] },
          what: { type: 'string' },
          howToSpot: { type: 'string' },
          seenIn: { type: 'array', items: { type: 'string' } },
          proposedFix: { type: 'string' },
          existingId: { type: 'string' },
        },
      },
    },
  },
};

const CRITIC_SCHEMA = {
  type: 'object',
  required: ['complete', 'gaps'],
  properties: { complete: { type: 'boolean' }, gaps: { type: 'array', items: { type: 'string' } } },
};

// ---------- Gate ----------
phase('Gate');
if (!reserve(0, 'gate')) return { round: ROUND, halted: true, reason: 'agent cap before gate' };
const gate = await agent(
  [
    'You are the gate checker for an evaluation harness. You may read files under spe/evals/.',
    `1. Read ${TICKETS_FILE}. Return every ticket as {id, subject, body}, copied exactly. Do not add labels.`,
    `2. Read ${ANSWERS}. Return only the list of ticket IDs it contains. Do not return any labels.`,
    `3. Run: python3 ${GRADER} --selftest`,
    '   Report whether the oracle answer passed, whether the empty answer failed, and whether the wrong answer failed. Put the raw output in output.',
  ].join('\n'),
  { label: 'gate: stage tickets and grader selftest', phase: 'Gate', schema: GATE_SCHEMA, model: MODEL },
);

const st = gate.selftest;
if (!(st.oraclePass && st.emptyFail && st.wrongFail)) {
  return { round: ROUND, halted: true, reason: 'grader selftest failed', selftest: st };
}
const ticketIds = gate.tickets.map((t) => t.id).sort();
const answerIds = gate.answerIds.slice().sort();
if (ticketIds.length !== EXPECTED_TASKS || JSON.stringify(ticketIds) !== JSON.stringify(answerIds)) {
  return {
    round: ROUND,
    halted: true,
    reason: `task set mismatch: expected ${EXPECTED_TASKS} tickets, found ${ticketIds.length} tickets and ${answerIds.length} answer IDs. This is a decision for the user.`,
  };
}

const tickets = LIMIT_TICKETS ? gate.tickets.slice(0, LIMIT_TICKETS) : gate.tickets;
const ticketById = Object.fromEntries(gate.tickets.map((t) => [t.id, t]));
const cells = [];
for (const cfg of CONFIGS) for (const t of tickets) cells.push({ cfg, ticket: t });
log(`Gate passed. ${cells.length} cells, ${cells.length * TRIALS} planned trials.`);

// ---------- Trials ----------
function trialPrompt(cell, dir, start, n) {
  const { cfg, ticket } = cell;
  return [
    'You are a harness driver for one cell of an evaluation of the "triage" support agent.',
    'You run a command and report its output. You do not judge, fix, or retry answers.',
    '',
    `Allowed paths: read and write only under ${dir}/ and ${OUT}/inputs/. Run only the runner command below.`,
    'Do not open, list, grep, or cat anything under spe/. Reading it voids the trial.',
    '',
    `1. If ${OUT}/inputs/${ticket.id}.json does not exist, write this JSON to it exactly:`,
    JSON.stringify({ id: ticket.id, subject: ticket.subject, body: ticket.body }),
    `2. For each k from ${start} to ${start + n - 1}, run this once as a fresh process:`,
    `   ${RUNNER} --config ${cfg} --ticket ${OUT}/inputs/${ticket.id}.json --out ${dir}/t<k>.json --transcript ${dir}/t<k>.transcript.jsonl`,
    `3. After each run, read ${dir}/t<k>.json. Copy label.category, label.priority, reply, and the metrics fields (runtime_s, tool_calls, tokens_in, tokens_out, tool_errors, cost_usd) into the entry for k.`,
    '   If a label value is missing or not in the allowed set, record it as "invalid".',
    '   If the command exits non-zero, set status to "harness_error". If it reports a rate limit, set status to "rate_limited". Put the first 300 characters of stderr in error. Do not rerun it.',
    'Return one entry per k with outFile and transcriptFile set to the paths above.',
  ].join('\n');
}

async function runCell(cell, start, want, tag) {
  const what = `${tag} ${cell.cfg}:${cell.ticket.id} t${start}-t${start + want - 1}`;
  const n = reserveTrials(want, what);
  if (n === 0) return [];
  const held = n * EST_TRIAL_USD;
  const dir = `${OUT}/${cell.cfg}/${cell.ticket.id}`;
  const base = { cfg: cell.cfg, ticket: cell.ticket.id, topUp: tag === 'topup' };
  try {
    const res = await agent(trialPrompt(cell, dir, start, n), {
      label: what,
      phase: tag === 'topup' ? 'Top-up' : 'Trials',
      schema: TRIAL_SCHEMA,
      model: MODEL,
    });
    const trials = (res.trials ?? []).map((t) => ({ ...t, ...base }));
    settle(held, trials.reduce((s, t) => s + (t.costUsd ?? (t.status === 'completed' ? EST_TRIAL_USD : 0)), 0));
    return trials;
  } catch (e) {
    settle(held, 0);
    return range(start, n).map((k) => ({ ...base, trial: k, status: 'harness_error', error: String(e).slice(0, 300) }));
  }
}

phase('Trials');
const records = new Map();
for (const t of await inWaves(cells, WAVE, (c) => runCell(c, 1, TRIALS, 'trial'))) {
  records.set(key(t.cfg, t.ticket, t.trial), t);
}
log(`Trials done. ${records.size} records. Spent about $${spentUsd.toFixed(2)}.`);

// ---------- Scan, Grade, Judge (reused after top-up) ----------
async function scanAll() {
  const voided = [];
  for (const cfg of CONFIGS) {
    if (!reserve(0, `scan ${cfg}`)) return { halted: true };
    const res = await agent(
      [
        'You are a leak scanner for an evaluation harness.',
        `Search every file matching ${OUT}/${cfg}/*/t*.transcript.jsonl for these strings: ${FORBIDDEN.join(', ')}`,
        'Use grep -n. Report every hit with ticket (the folder name), trial (the number after t), file, and the first 200 characters of the matching line.',
        `Also list every ${OUT}/${cfg}/*/t<k>.json that has no matching transcript file as missing.`,
        'Do not read the answer key or the graders.',
      ].join('\n'),
      { label: `scan ${cfg}`, phase: 'Scan', schema: SCAN_SCHEMA, model: MODEL },
    );
    for (const h of res.hits) voided.push({ cfg, ticket: h.ticket, trial: h.trial, why: `read ${h.match}` });
    for (const m of res.missing) voided.push({ cfg, ticket: m.ticket, trial: m.trial, why: 'no transcript to verify' });
  }
  for (const v of voided) {
    const r = records.get(key(v.cfg, v.ticket, v.trial));
    if (r) { r.voided = true; r.voidReason = v.why; }
  }
  log(`Scan: ${voided.length} trial(s) voided.`);
  return { voided };
}

async function gradeAll() {
  for (const cfg of CONFIGS) {
    if (!reserve(0, `grade ${cfg}`)) return { halted: true, reason: 'agent cap at grade' };
    const res = await agent(
      [
        'You run the code grader for an evaluation harness and report its output.',
        `Run: python3 ${GRADER} --answers ${ANSWERS} --runs ${OUT}/${cfg} --json`,
        'Return the per-trial rows exactly as the grader prints them (ticket, trial, categoryOk, priorityOk).',
        'Do not grade anything by hand. If the grader exits non-zero, return ok false and the error text.',
      ].join('\n'),
      { label: `grade ${cfg}`, phase: 'Grade', schema: GRADE_SCHEMA, model: MODEL },
    );
    if (!res.ok) return { halted: true, reason: `grader error on ${cfg}: ${res.error}` };
    for (const g of res.results) {
      const r = records.get(key(cfg, g.ticket, g.trial));
      if (r) { r.categoryOk = g.categoryOk; r.priorityOk = g.priorityOk; r.labelPass = g.categoryOk && g.priorityOk; }
    }
  }
  return { halted: false };
}

async function judge(onlyNew) {
  const byTicket = {};
  for (const r of records.values()) {
    if (r.status !== 'completed' || r.voided || !r.reply) continue;
    if (onlyNew && r.tonePass !== undefined) continue;
    (byTicket[r.ticket] ??= []).push(r);
  }
  const jobs = Object.entries(byTicket).map(([tid, rs]) => async () => {
    const what = `judge ${tid} (${rs.length} replies)`;
    if (!reserve(EST_JUDGE_USD, what)) return;
    const shuffled = seededShuffle(rs, `${RR}-${tid}-${rs.length}`);
    const rid = new Map(shuffled.map((r, i) => [`R${i + 1}`, r]));
    const t = ticketById[tid];
    try {
      const res = await agent(
        [
          `You are a tone judge. Read the rubric at ${RUBRIC} and apply it exactly.`,
          'Score each reply on its own against the rubric. Do not rank replies against each other.',
          'You judge tone only. Do not judge the category or the priority.',
          '',
          `Ticket subject: ${t.subject}`,
          `Ticket body:\n${t.body}`,
          '',
          ...[...rid.entries()].map(([id, r]) => `--- ${id} ---\n${r.reply}`),
        ].join('\n'),
        { label: what, phase: 'Judge', schema: JUDGE_SCHEMA, model: MODEL },
      );
      for (const s of res.scores) {
        const r = rid.get(s.rid);
        if (r) { r.tonePass = s.tonePass; r.toneScore = s.score; r.toneReason = s.reason; }
      }
      settle(EST_JUDGE_USD);
    } catch (e) {
      settle(EST_JUDGE_USD, 0);
      log(`Judge harness error on ${tid}: ${String(e).slice(0, 200)}`);
    }
  });
  for (let i = 0; i < jobs.length; i += WAVE) await parallel(jobs.slice(i, i + WAVE));
}

phase('Scan');
if ((await scanAll()).halted) return { round: ROUND, halted: true, reason: 'agent cap at scan', skipped };

phase('Grade');
let g = await gradeAll();
if (g.halted) return { round: ROUND, halted: true, reason: g.reason, skipped };

phase('Judge');
await judge(false);

// ---------- Top-up ----------
phase('Top-up');
const cellStats = {};
for (const r of records.values()) {
  if (r.topUp || r.status !== 'completed' || r.voided || r.labelPass === undefined) continue;
  const k = `${r.cfg}|${r.ticket}`;
  (cellStats[k] ??= { pass: 0, fail: 0 });
  r.labelPass ? cellStats[k].pass++ : cellStats[k].fail++;
}
const split = Object.entries(cellStats).filter(([, s]) => s.pass > 0 && s.fail > 0).map(([k]) => k);
const topUpCells = [];
let topUpBudget = TOPUP_MAX;
for (const k of split) {
  if (topUpBudget <= 0) { skipped.push({ what: `topup ${k}`, reason: 'top-up cap' }); continue; }
  const [cfg, tid] = k.split('|');
  const n = Math.min(TOPUP_PER_CELL, topUpBudget);
  topUpBudget -= n;
  topUpCells.push({ cell: { cfg, ticket: ticketById[tid] }, n });
}
log(`Top-up: ${split.length} split cell(s), ${topUpCells.length} topped up, ${TOPUP_MAX - topUpBudget} extra trial(s).`);
if (topUpCells.length) {
  for (const t of await inWaves(topUpCells, WAVE, ({ cell, n }) => runCell(cell, TRIALS + 1, n, 'topup'))) {
    records.set(key(t.cfg, t.ticket, t.trial), t);
  }
  if ((await scanAll()).halted) return { round: ROUND, halted: true, reason: 'agent cap at rescan', skipped };
  g = await gradeAll();
  if (g.halted) return { round: ROUND, halted: true, reason: g.reason, skipped };
  await judge(true);
}

// ---------- Synthesis ----------
phase('Synthesis');
function summarize(includeTopUp) {
  const out = {};
  for (const cfg of CONFIGS) {
    const all = [...records.values()].filter((r) => r.cfg === cfg && (includeTopUp || !r.topUp));
    const ok = all.filter((r) => r.status === 'completed' && !r.voided && r.labelPass !== undefined);
    const judged = ok.filter((r) => r.tonePass !== undefined);
    const rate = (xs, f) => (xs.length ? +(xs.filter(f).length / xs.length).toFixed(3) : null);
    const mean = (xs, f) => (xs.length ? +(xs.reduce((s, r) => s + (f(r) ?? 0), 0) / xs.length).toFixed(2) : null);
    out[cfg] = {
      completed: ok.length,
      voided: all.filter((r) => r.voided).length,
      harnessErrors: all.filter((r) => r.status !== 'completed').length,
      categoryAcc: rate(ok, (r) => r.categoryOk),
      priorityAcc: rate(ok, (r) => r.priorityOk),
      bothAcc: rate(ok, (r) => r.labelPass),
      tonePassRate: rate(judged, (r) => r.tonePass),
      toneJudged: judged.length,
      meanRuntimeS: mean(ok, (r) => r.runtimeS),
      meanToolCalls: mean(ok, (r) => r.toolCalls),
      meanTokens: mean(ok, (r) => (r.tokensIn ?? 0) + (r.tokensOut ?? 0)),
      toolErrorsPerTrial: mean(ok, (r) => r.toolErrors),
    };
  }
  return out;
}
const planned = summarize(false);     // headline: the planned trials only, comparable to the prediction
const withTopUp = summarize(true);    // reported separately because top-ups weight split cells more

const failing = [...records.values()]
  .filter((r) => r.status === 'completed' && !r.voided && (r.labelPass === false || r.tonePass === false))
  .map((r) => ({ cfg: r.cfg, ticket: r.ticket, trial: r.trial, categoryOk: r.categoryOk, priorityOk: r.priorityOk, tonePass: r.tonePass, toneReason: r.toneReason, outFile: r.outFile, transcriptFile: r.transcriptFile }));

let failures = { failureTypes: [] };
if (failing.length && reserve(0, 'failure analysis')) {
  failures = await agent(
    [
      'You are the failure analyst for an evaluation of the "triage" support agent.',
      `You may read ${ANSWERS}, the run outputs and transcripts listed below, and spe/failures.md.`,
      'Group the failing trials into failure types. For each type give a short name, a kind, what happens, how to spot it, the trials it was seen in (cfg:ticket:trial), and a proposed fix.',
      'If a type matches an entry already in spe/failures.md, put its F-number in existingId. Otherwise put "new".',
      'Count harness errors as harness failures, never as agent failures. If a grader or judge result looks wrong, report it as a grader or judge failure.',
      '',
      JSON.stringify(failing),
    ].join('\n'),
    { label: 'failure analysis', phase: 'Synthesis', schema: FAILURE_SCHEMA, model: MODEL },
  );
}

const expected = cells.length * TRIALS;
let critic = { complete: false, gaps: ['critic skipped by agent cap'] };
if (reserve(0, 'completeness critic')) {
  critic = await agent(
    [
      'You are a completeness critic for an evaluation run. Find gaps that would make the results misleading.',
      'Check: every planned cell has its trials or a logged skip, voided and errored trials are excluded from accuracy, every completed trial has grader rows, every completed non-voided trial has a tone score, top-up trials are kept out of the headline numbers, and spend stayed under the cap.',
      `Also check that the configs are exactly ${CONFIGS.join(' and ')}, and that each config changes one thing.`,
      'Report the Opus-judges-Sonnet same-family limit as a gap.',
      '',
      JSON.stringify({ expectedPlannedTrials: expected, recordCount: records.size, planned, withTopUp, skipped, capUsd: CAP_USD, spentUsdEstimate: +spentUsd.toFixed(2), agentsUsed }),
    ].join('\n'),
    { label: 'completeness critic', phase: 'Synthesis', schema: CRITIC_SCHEMA, model: MODEL },
  );
}

log(`Done. Spent about $${spentUsd.toFixed(2)} of $${CAP_USD}. ${skipped.length} skip(s).`);

return {
  round: ROUND,
  roundTag: RR,
  configs: CONFIGS,
  trialsPerCell: TRIALS,
  tickets: tickets.length,
  outDir: OUT,
  headline: planned,
  withTopUp,
  splitCells: split,
  voided: [...records.values()].filter((r) => r.voided).map((r) => ({ cfg: r.cfg, ticket: r.ticket, trial: r.trial, why: r.voidReason })),
  harnessErrors: [...records.values()].filter((r) => r.status !== 'completed').map((r) => ({ cfg: r.cfg, ticket: r.ticket, trial: r.trial, status: r.status, error: r.error })),
  skipped,
  spend: { capUsd: CAP_USD, spentUsdEstimate: +spentUsd.toFixed(2), agentsUsed, maxAgents: MAX_AGENTS, note: 'Triage cost comes from runner cost_usd. Judge cost is an unmeasured estimate.' },
  failures: failures.failureTypes,
  critic,
  notes: ['Tone judge is Opus, the same family as the Sonnet agent under test.', 'Headline numbers use the planned trials only. Top-up trials are reported separately.'],
};
